class Solution:
    def followsRhythm(self, pattern: str, sentence: str) -> bool:
        words = sentence.split(" ")
        if len(words) != len(pattern):
            return False
        for i in range(len(words)):
            for j in range(i + 1, len(words)):
                if (pattern[i] == pattern[j]) != (words[i] == words[j]):
                    return False
        return True

