bool followsRhythm(char* pattern, char* sentence) {
    int n = strlen(pattern), count = 0;
    char* copy = malloc(strlen(sentence) + 1);
    strcpy(copy, sentence);
    char** words = malloc((strlen(sentence) / 2 + 2) * sizeof(char*));
    for (char* w = strtok(copy, " "); w; w = strtok(NULL, " ")) words[count++] = w;
    bool ok = count == n;
    for (int i = 0; i < n && ok; i++)
        for (int j = i + 1; j < n && ok; j++)
            if ((pattern[i] == pattern[j]) != (strcmp(words[i], words[j]) == 0)) ok = false;
    free(words); free(copy);
    return ok;
}

