class Solution {
    public boolean followsRhythm(String pattern, String sentence) {
        String[] words = sentence.split(" ");
        if (words.length != pattern.length()) return false;
        Map<Character, String> toWord = new HashMap<>();
        Map<String, Character> toLetter = new HashMap<>();
        for (int i = 0; i < words.length; i++) {
            char p = pattern.charAt(i);
            String w = words[i];
            if (!toWord.computeIfAbsent(p, k -> w).equals(w)) return false;
            if (toLetter.computeIfAbsent(w, k -> p) != p) return false;
        }
        return true;
    }
}

