        vector<string> words;
        stringstream in(sentence);
        for (string w; in >> w;) words.push_back(w);
        if (words.size() != pattern.size()) return false;
        unordered_map<char, string> toWord;
        unordered_map<string, char> toLetter;
        for (size_t i = 0; i < words.size(); i++) {
            auto a = toWord.emplace(pattern[i], words[i]).first;
            auto b = toLetter.emplace(words[i], pattern[i]).first;
            if (a->second != words[i] || b->second != pattern[i]) return false;
        }
        return true;
    }
};

